contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(uint depositAmount, uint dummyMin, address logAddr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure we have Ether to send for Deposit
        require(address(this).balance >= depositAmount);

        // Configure MinSum and Log before initialization (allowed only before Initialized())
        c.SetMinSum(dummyMin); if (__ESBMC_reverted()) return;
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;

        // observe before-values
        uint before_c_bal = address(c).balance;
        uint before_my_balInC = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // perform Deposit (top-level state-changing call) and capture whether it reverted
        bool deposit_reverted;
        c.Deposit{value: depositAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            deposit_reverted = true;
        } else {
            deposit_reverted = false;
        }

        // observe after-values
        uint after_c_bal = address(c).balance;
        uint after_my_balInC = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // General assertion: if Deposit did not revert, then both the contract's Ether balance
        // and this caller's recorded balance increased by exactly depositAmount.
        assert(
            deposit_reverted || (
                after_my_balInC == before_my_balInC + depositAmount
                && after_c_bal == before_c_bal + depositAmount
            )
        );
    }

    // allow receiving Ether for callbacks (not used here but harmless)
    receive() external payable { }
}

